// Helpers for list views.
const ELLIPSIS = '...';

export function truncate(text, max) {
  if (text.length <= max) return text;
  // Keep the result within max characters, including the ellipsis.
  if (max <= ELLIPSIS.length) return ELLIPSIS.slice(0, max);
  return text.slice(0, max - ELLIPSIS.length) + ELLIPSIS;
}

export function capitalize(text) {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { truncate, capitalize } from '../src/text.js';

test('short text is left alone', () => assert.equal(truncate('hi', 5), 'hi'));
test('capitalize raises the first letter', () => assert.equal(capitalize('ab'), 'Ab'));

test('text that fits exactly is left alone', () => {
  assert.equal(truncate('abcde', 5), 'abcde');
});

test('cut text never exceeds max and ends in an ellipsis', () => {
  const text = 'the quick brown fox jumps over the lazy dog';
  for (let max = 4; max <= 30; max++) {
    const out = truncate(text, max);
    assert.ok(out.length <= max, `length ${out.length} > max ${max}`);
    assert.ok(out.endsWith('...'), `expected ellipsis for max ${max}: ${out}`);
    assert.ok(text.startsWith(out.slice(0, -3)), 'truncate keeps the prefix');
  }
});

test('one character over max is cut to fit', () => {
  const out = truncate('abcdef', 5);
  assert.equal(out, 'ab...');
  assert.ok(out.length <= 5);
});

test('tiny budgets still return at most max characters', () => {
  for (const max of [0, 1, 2, 3]) {
    const out = truncate('hello world', max);
    assert.ok(out.length <= max, `length ${out.length} > max ${max}`);
    assert.equal(out, '.'.repeat(max));
  }
});

